package com.matthew.rawlens

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * End-to-end parity for the full RT Color-propagation reconstruction chain
 * on a 32x32 scene: thresholds, ROI, accumulator, downsample, directional
 * scans, per-pixel correction, gamma guide, four guided-filter passes, and
 * bilinear merge-back.
 *
 * Goldens below were machine-generated from the float32 C++ oracle running
 * the same chain with verbatim stage code (see /tmp/rt_hlmap_oracle.cpp); the
 * generator script that embedded them read /tmp/rt_hlmap_goldens.txt, so no
 * hand transcription is involved. Final pixels assert per-element ULP
 * distance: the chain inherits JVM FMA fusion plus libm differences in the
 * gamma table, all measured by the bound below.
 */
class RtHlEndToEndTest {
    internal fun scene(): Array<Array<FloatArray>> {
        val h = 32
        val w = 32
        val red = Array(h) { FloatArray(w) }
        val green = Array(h) { FloatArray(w) }
        val blue = Array(h) { FloatArray(w) }
        for (i in 0 until h) {
            for (j in 0 until w) {
                val base = ((i * 131 + j * 137 + 7) % 1009).toFloat() / 1009f * 40000f
                val ring = i in 10 until 22 && j in 10 until 22
                val blob = i in 12 until 20 && j in 12 until 20
                var v = base
                if (ring) v = 45000f + ((i * 17 + j * 29) % 500).toFloat()
                if (blob) v = 65000f
                red[i][j] = v
                green[i][j] = v * 0.98f
                blue[i][j] = v * 1.01f
            }
        }
        return arrayOf(red, green, blue)
    }

    private fun maxUlp(expected: List<String>, actual: Array<FloatArray>): Long {
        val flat = expected.flatMap { it.split(" ") }
        var k = 0
        var worst = 0L
        for (row in actual) for (x in row) {
            val e = flat[k].toLong(16)
            val a = x.toBits().toLong() and 0xffffffffL
            fun t(u: Long) = if (u and 0x80000000L == 0L) u else 0x100000000L - u
            val d = kotlin.math.abs(t(e) - t(a))
            if (d > worst) worst = d
            k++
        }
        assertEquals(flat.size, k)
        return worst
    }

    private fun assertUlpClose(label: String, expected: List<String>, actual: Array<FloatArray>, bound: Long) {
        val worst = maxUlp(expected, actual)
        assertTrue("$label maxUlp=$worst exceeds $bound", worst <= bound)
    }

    @Test
    fun fullChainMatchesOracle() {
        val (red, green, blue) = scene()
        val t = RtColorPropagation.computeThresholds(
            floatArrayOf(66000f, 66000f, 66000f),
            floatArrayOf(63000f, 64000f, 63500f)
        )
        val roi = RtHighlightMap.findRoi(red, green, blue, t.maxF)!!
        val acc = RtHighlightMap.accumulateAndGate(red, green, blue, t.thresh, t.maxF, roi)
        val hil = RtHighlightMap.downsample(acc.full)
        val maps = RtHighlightMap.directionalExtend(hil, 8, 8)
        val w2 = roi.width / 2
        val h2 = roi.height / 2
        val rbuf = Array(h2) { FloatArray(w2) }
        val gbuf = Array(h2) { FloatArray(w2) }
        val bbuf = Array(h2) { FloatArray(w2) }
        val mask = Array(h2) { FloatArray(w2) }
        RtGuidedFilter.rescaleNearestInto(red, roi.minX, roi.minY, roi.width, roi.height, rbuf)
        RtGuidedFilter.rescaleNearestInto(green, roi.minX, roi.minY, roi.width, roi.height, gbuf)
        RtGuidedFilter.rescaleNearestInto(blue, roi.minX, roi.minY, roi.width, roi.height, bbuf)
        val xyzcam = floatArrayOf(0.2126f, 0.7152f, 0.0722f)
        val gamma = RtGuidedFilter.gammaTable()
        // RT builds the guide from the rescaled originals, before the
        // correction loop overwrites corrected cells in the buffers.
        val guide = Array(h2) { y ->
            FloatArray(w2) { x ->
                RtGuidedFilter.lutSample(
                    gamma,
                    RtGuidedFilter.rgbLuminance(rbuf[y][x], gbuf[y][x], bbuf[y][x], xyzcam)
                )
            }
        }
        RtHighlightMap.reconstructAndFill(red, green, blue, t, maps, roi, rbuf, gbuf, bbuf, mask)
        val params = RtGuidedFilter.guidedParams(2)
        RtGuidedFilter.highlightGuidedPass(guide, mask, rbuf, gbuf, bbuf, params)
        RtHighlightMap.mergeBack(red, green, blue, rbuf, gbuf, bbuf, mask, roi)
        assertUlpClose("finalR", GOLDEN_R, red, PIXEL_BOUND)
        assertUlpClose("finalG", GOLDEN_G, green, PIXEL_BOUND)
        assertUlpClose("finalB", GOLDEN_B, blue, PIXEL_BOUND)
        assertUlpClose("mask", GOLDEN_M, mask, MASK_BOUND)
        assertUlpClose("guide", GOLDEN_GD, guide, GUIDE_BOUND)
    }

